insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('091ddc25-ab7c-4ef5-a137-d03e3867dabd','fb4e5625-f90b-4f1e-8cfd-73c1805add95',2027,'Georgetown University''s McDonough School of Business provides graduates with essential global, ethical, analytical, financial, and diverse perspectives on the economies of our nation and the world. Describe your primary motivations for studying business at Georgetown University.',null,true,'program_conditional','Essay 2 - McDonough School of Business 지원 동기',null,'05ba724a-dcc1-4e3a-9357-430e9c71e109',null,null,'McDonough School of Business',null,null,null,500,null,null,'confirmed_current_year','2026-09-24','단과대별 Essay 2, McDonough School of Business 지원자용. 공식 사이트 원문 확인.');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('5c1eed72-e0e2-4245-8b5b-e1cc1ac27196','fb4e5625-f90b-4f1e-8cfd-73c1805add95',2027,'Georgetown University''s Walsh School of Foreign Service was founded more than a century ago to prepare generations of leaders with the foundational skills to address global issues. Describe your primary motivations for studying international affairs at Georgetown University and dedicating your undergraduate studies toward a future in global service.',null,true,'program_conditional','Essay 2 - Walsh School of Foreign Service 지원 동기',null,'206806e0-8e0c-4484-a0fa-656caf5e0814',null,null,'Walsh School of Foreign Service',null,null,null,500,null,null,'confirmed_current_year','2026-09-24','단과대별 Essay 2, Walsh School of Foreign Service 지원자용. 공식 사이트 원문 확인.');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('10d4968a-cc88-4496-8d6a-04b2c71dcfb2','fb4e5625-f90b-4f1e-8cfd-73c1805add95',2027,'Georgetown University''s School of Health was founded to advance the health and well-being of people locally, nationally, and globally through innovative research, the delivery of interdisciplinary education, and transformative engagement of communities. Describe the factors that influenced your interest in studying health care at Georgetown University, specifically addressing your intended related major: Global Health, Health Care Management & Policy, or Human Science.',null,true,'program_conditional','Essay 2 - School of Health 지원 동기',null,'14f1dfca-2b2e-4d8e-b85f-ab0c56587789',null,null,'School of Health',null,null,null,500,null,null,'confirmed_current_year','2026-09-24','단과대별 Essay 2, School of Health 지원자용. 공식 사이트 원문 확인.');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('d8f3a6e6-920e-48a1-9504-53186f3bdd76','fb4e5625-f90b-4f1e-8cfd-73c1805add95',2027,'Georgetown University''s Berkley School of Nursing is committed to the formation of ethical, empathetic, and transformational nursing leaders. Describe the factors that have influenced your interest in studying Nursing at Georgetown University.',null,true,'program_conditional','Essay 2 - Berkley School of Nursing 지원 동기',null,'89947a75-3927-42fa-89c4-2e829850248a',null,null,'Berkley School of Nursing',null,null,null,500,null,null,'confirmed_current_year','2026-09-24','단과대별 Essay 2, Berkley School of Nursing 지원자용. 공식 사이트 원문 확인.');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('19d7591c-f154-4118-a71b-720f5f178c67','fb4e5625-f90b-4f1e-8cfd-73c1805add95',2027,'Through this joint program between the College of Arts & Sciences and the Earth Commons Institute, you''ll explore theories and practical skills in the classroom, in the field, and around the world, and put it all together to make a difference. Describe your primary motivations for studying environment and sustainability at Georgetown University to effect positive change in the world.',null,true,'program_conditional','Essay 2 - Earth Commons Institute 지원 동기',null,'a7b77d8e-e48a-4a4f-8d4c-ed86c4237a9b',null,null,'Earth Commons Institute',null,null,null,500,null,null,'confirmed_current_year','2026-09-24','단과대별 Essay 2, Earth Commons Institute 지원자용. 공식 사이트 원문 확인.');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('1ee9dc61-1ede-4c75-9932-06526cb98864','fb4e5625-f90b-4f1e-8cfd-73c1805add95',2027,'For nearly 50 years, Georgetown University''s McCourt School of Public Policy has equipped leaders and changemakers with the interdisciplinary skills to address local, national and global policy problems. Undergraduate public policy students at Georgetown will have the unique opportunity to live and study on two campuses, spending their first two years immersed on the Hilltop, before completing the second half of their time at Georgetown on the Capitol Campus, immersed in the policy world. Describe your primary motivations for studying public policy at Georgetown University and dedicating your undergraduate studies toward a future related to public service.',null,true,'program_conditional','Essay 2 - McCourt School of Public Policy 지원 동기',null,'773fdf23-7f7d-4c93-8346-067b619634a2',null,null,'McCourt School of Public Policy',null,null,null,500,null,null,'confirmed_current_year','2026-09-24','단과대별 Essay 2, McCourt School of Public Policy 지원자용. 공식 사이트 원문 확인.');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('d74c66c0-1c45-4c68-9f24-c2e3298af064','fb4e5625-f90b-4f1e-8cfd-73c1805add95',2027,'Founded in 1789, the Georgetown College of Arts & Sciences is committed to the Jesuit traditions of an integrated education and of productive research in the natural sciences, humanities, social sciences, and fine arts. Describe your interest in studying in the College of Arts & Sciences. Applicants interested in the sciences, mathematics, or languages are encouraged to make specific reference to their choice of major.',null,true,'program_conditional','Essay 2 - College of Arts & Sciences 지원 동기',null,'15255d0c-af98-427c-b567-86a7533fd69f',null,null,'College of Arts & Sciences',null,null,null,500,null,null,'confirmed_current_year','2026-09-24','단과대별 Essay 2, College of Arts & Sciences 지원자용. 공식 사이트 원문 확인.');
