insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('6b206686-e9be-4493-a91b-2a6605b1f168','c8682a44-e0b7-4ae4-b2f2-01da46001eb3',2027,'In 200-400 words, describe your academic and career plans and any special interest (for example, undergraduate research, academic interests, leadership opportunities, etc.) that you are eager to pursue as an undergraduate at Indiana University. Also, if you encountered any unusual circumstances, challenges, or obstacles in pursuit of your education, you may share those experiences and how you overcame them. Please note that this essay may be used for scholarship consideration.',null,true,'school_specific','Academic/career plans (Apply IU applicants)',null,'baf05d54-a467-4340-8f5c-c0a7355e3ebb',null,null,'Apply IU platform only; Common App applicants use a Common App essay instead',null,null,200,400,null,null,'unconfirmed_current_year',null,null);
