insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('e8994f32-1c72-4ea5-90ab-900add3ee8cb','d63c0f9c-e36b-4508-bcdd-828f8fd6a974',2027,null,null,true,'common_app','Common App/Coalition Personal Essay (No Miami Supplement Found)',null,'e6d578e3-80c9-482f-981d-e8060aa012c3',null,null,null,null,null,null,null,null,null,'unconfirmed_current_year','2026-09-24','공식 페이지 직접 fetch 실패(SSL 인증서 오류)로 제3자 검색 결과 기반. Miami University(Ohio)는 Common App/Coalition App 사용, 자체 추가 에세이 요구 확인 안 됨. 재확인 필요.');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('1aa005e2-9cff-4ecc-9b17-a3ff59d93871','6e7b5ea1-7f91-4c1c-b7e7-bcd2c1f76d1c',2026,'Choose one: (1) Some students have an interest or talent that is so meaningful they believe their application would be incomplete without it; (2) The lessons we take from obstacles we encounter can be fundamental to later success. Recount a time when you faced a challenge, setback, or failure. How did it affect you, and what did you learn?; (3) Reflect on a time when you questioned or challenged a belief or idea. What prompted your thinking? What was the outcome?; (4) Describe a time you experienced unexpected gratitude or kindness and its impact on your motivation; (5) Describe an accomplishment, event, or realization that sparked personal growth; (6) Describe an engaging topic, idea, or concept that captivates you and why; (7) Share an essay on any topic of your choice, including previously written work or a self-designed prompt.',null,true,'common_app','Required Essay (choose 1 of 7 prompts)',null,'feabf3fb-e63d-45fc-b1db-22531b7860b5',1,7,null,null,null,250,650,null,null,'confirmed_current_year','2026-09-24','Official admissions.msu.edu page; applicant selects one of 7 listed prompts');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('c234de22-2e68-4e4d-b456-f4300351c04a','01540326-bfd6-4fad-9b8a-30436e8be296',2027,null,null,false,'school_specific','No Essay Required for Guaranteed Admission (Personal Statement Required Only for Admission-by-Review)',null,'502d787f-201a-406d-9e8b-10d6befdcfce',null,null,null,null,null,null,null,null,null,'confirmed_current_year','2026-09-24','MTSU 공식 How to Apply 페이지 직접 확인: 일반(guaranteed admission) 대상자는 에세이 불요구, "admission by review" 대상자만 personal statement form 제출 필요.');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('21f5f725-758c-47f8-a032-66066711d320','96d1fcf5-9d32-49f2-b35c-21fb97e46ec0',2027,null,null,false,'common_app','No Essay Required (Freshman Admission)',null,'af02a6bf-bf7f-4fcb-9cad-99e591758efc',null,null,null,null,null,null,null,null,null,'confirmed_current_year','2026-09-24','Mississippi State 공식 Freshman Admissions 페이지 직접 확인: 지원서/수수료/성적표/시험점수(선택)만 명시, 에세이 언급 없음.');
