insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('0bf29b22-e1b8-4cbe-8105-b6e72f56525b','b49b4829-4477-4b9c-9b3f-370b34f61936',2027,null,null,false,'common_app','No Essay Required (General Admission)',null,'30463981-e3be-440b-932b-10a1ff63ee4a',null,null,null,null,null,null,null,null,null,'confirmed_current_year','2026-09-24','Morgan State 공식 Freshman Applicants/Admission Requirements 페이지 2건 직접 확인: 완성된 지원서 구성요소(지원서/성적표/시험점수/지원비)에 에세이 미포함. 단, 제3자 출처(prepscholar)는 "500단어 선택 에세이" 언급하나 공식 페이지에서는 확인 안 됨 — 재검증 필요 표시.');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('ac6cc610-d6a3-4e06-94d1-16123b4eda84','db579278-0fe6-4fc4-9ad1-0f8230dccf83',2027,null,null,true,'common_app','Common App Personal Essay Required (No NJIT Supplement)',null,'ffe21398-16e4-4f15-bb75-e18747651c4b',null,null,null,null,null,250,650,null,null,'confirmed_current_year','2026-09-24','NJIT 공식 How We Evaluate Applicants 페이지 직접 확인: "Included in the Common Application is an essay... to learn more about you as an individual." Dorman Honors College는 별도 에세이 추가 필요(미포함).');
