insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('83a48666-18fe-4da1-827a-e903b5692007','96748cc3-6e50-4011-b236-8cc1dc870145',2027,null,null,false,'common_app','Essay Requirement Unconfirmed (No Essay per third-party summary)',null,'d773a6e5-a98b-4212-aec0-d50195852d82',null,null,null,null,null,null,null,null,null,'unconfirmed_current_year','2026-09-24','NAU 공식 how-to-apply 페이지가 지원 경로만 설명하고 서류 체크리스트를 제공하지 않아 직접 확인 실패(이전 세션에서도 URL 변경으로 확인 실패한 이력 있음). 검색 요약 기준 "essay not required, optional"이나 공식 페이지 미확인. 다음 세션 재탐색 필요.');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('0da5f055-537d-4a6e-ad1e-a42ae7c3f2fb','8a3e4a90-a9a3-4810-b37d-4dc5dd9564eb',2027,'Northwestern is a place where people with diverse backgrounds from all over the world can study, live, and talk with one another. This range of experiences and viewpoints immeasurably enriches learning. How might your individual background contribute to this diversity of perspectives in Northwestern''s classrooms and around our campus?',null,false,'school_specific','Diversity of Perspectives (선택)',null,'ffb163c6-eba5-454f-9a56-5f4e92ff2a9c',2,5,null,null,null,null,200,null,null,'unconfirmed_current_year',null,'선택 그룹(5개 중 1~2개 선택) — select_count=2는 상한값, 실제 규칙은 "1~2개 선택"(notes 참고).');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('f4d69bbb-fc0d-4e5b-9edb-a6e7ad148d38','8a3e4a90-a9a3-4810-b37d-4dc5dd9564eb',2027,'Northwestern''s location is special: on the shore of Lake Michigan, steps from downtown Evanston, just a few miles from Chicago. What aspects of our location are most compelling to you, and why?',null,false,'school_specific','Location and Geography (선택)',null,'7c884ed2-2aa6-4e35-8498-ad4dbf45d599',2,5,null,null,null,null,200,null,null,'unconfirmed_current_year',null,'선택 그룹(5개 중 1~2개 선택) — select_count=2는 상한값, 실제 규칙은 "1~2개 선택"(notes 참고).');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('3f6b5952-e49f-4973-bfcd-50bf222cd82f','8a3e4a90-a9a3-4810-b37d-4dc5dd9564eb',2027,'Community and belonging matter at Northwestern. Tell us about one or more communities, networks, or student groups you see yourself connecting with on campus.',null,false,'school_specific','Community and Belonging (선택)',null,'83f19c1a-1576-4bd7-9593-1bc2374725eb',2,5,null,null,null,null,200,null,null,'unconfirmed_current_year',null,'선택 그룹(5개 중 1~2개 선택) — select_count=2는 상한값, 실제 규칙은 "1~2개 선택"(notes 참고).');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('7f9e3a76-74b3-4fbf-ba2d-da857e80d1ce','8a3e4a90-a9a3-4810-b37d-4dc5dd9564eb',2027,'Northwestern fosters a distinctively interdisciplinary culture. We believe discovery and innovation thrive at the intersection of diverse ideas, perspectives, and academic interests. Within this setting, if you could dream up an undergraduate class, research project, or creative effort (a start-up, a design prototype, a performance, etc.), what would it be? Who might be some ideal classmates or collaborators?',null,false,'school_specific','Interdisciplinary Innovation (선택)',null,'94981c72-2896-4447-830c-0f48d44b4787',2,5,null,null,null,null,200,null,null,'unconfirmed_current_year',null,'선택 그룹(5개 중 1~2개 선택) — select_count=2는 상한값, 실제 규칙은 "1~2개 선택"(notes 참고).');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('1acaae19-08c8-47ae-8f64-50466be17c41','8a3e4a90-a9a3-4810-b37d-4dc5dd9564eb',2027,'Painting "The Rock" is a tradition at Northwestern that invites all forms of expression—students promote campus events or extracurricular groups, support social or activist causes, show their Wildcat spirit (what we call "Purple Pride"), celebrate their culture, and more. What would you paint on The Rock, and why?',null,false,'school_specific','The Rock Painting Prompt (선택)',null,'3545f080-348c-4fd9-8837-d75c49dc10ce',2,5,null,null,null,null,200,null,null,'unconfirmed_current_year',null,'선택 그룹(5개 중 1~2개 선택) — select_count=2는 상한값, 실제 규칙은 "1~2개 선택"(notes 참고).');
