insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('237192d8-8454-40c4-adec-57eb28513146','a899e897-1113-464c-84ae-c4d479748829',2026,'Pepperdine is a Christian university where all are welcomed and encouraged to challenge each other in the pursuit of truth. Students, faculty, and staff members from all backgrounds participate in conversations of faith inside and outside of the classroom. Considering that Pepperdine is a Christian university, why are you interested in attending and how would you contribute to conversations of faith on campus?',null,true,'school_specific','Why Pepperdine / Faith Community',null,'54581be5-b045-4356-8169-609161ec68e0',null,null,null,null,null,300,500,null,null,'prior_year_reference',null,'CEA guide dated 2025-26 cycle; recheck for 2026-27.');
