insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('e3873e92-f5ad-4a38-88a0-dd96fea18b73','e79fcd05-b58c-49e6-88c4-d2539a7a095c',2027,'Share your aspirations and how you will use your time at UMass Lowell, and discuss how your communities have influenced you.',500,false,'school_specific','Aspirations & Community Essay (선택)',null,'0f89f03b-af8a-4463-b917-2283f4fd7d6b',null,null,null,null,null,250,null,null,null,'unconfirmed_current_year',null,'collegeessayadvisors.com UMass Lowell 2025-26 가이드 기반(2026-27 공식 페이지 직접 재확인 필요 — uml.edu/admissions). 선택(optional) 에세이 2개 중 첫번째만 기록, 두번째(자기소개/기여) 선택문항은 미기록.');
insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('871b8e01-f8cf-466d-9e3c-9fb0c51981d8','e79fcd05-b58c-49e6-88c4-d2539a7a095c',2026,'We invite you to dream big and use this space to share your aspirations for your best self and how you will use your time at UMass Lowell to accomplish your goals. The "you" that will join us encompasses multiple identities, some visible and others not, and participates in multiple communities. Your communities may include various aspects of your lived experiences, such as the families and communities with whom you live, work, play, worship, or even your ethnicity, or gender. This essay prompt is an invitation to talk about the influence of one or more of your communities on your life and your future at UMass Lowell and beyond.',null,true,'school_specific','Community/Why Essay',null,'19fb11c5-d764-4e1c-828b-811a54c1e894',null,null,null,null,null,null,500,null,null,'unconfirmed_current_year',null,'CEA 2026-27 guide');
