insert into university_essay_prompts (id, university_id, cycle_year, prompt_text, word_limit, is_required, prompt_type, title, topic_summary, selection_group_id, select_count, group_size, applies_to_school, applies_to_majors, application_paths, word_limit_min, word_limit_max, char_limit, source_url_id, prompt_status, last_verified_at, notes) values ('ccaa4c31-4d8f-4ed9-b035-e7047021ffa5','ace7c18b-d72e-4d5a-a717-82ab45f212a8',2027,null,null,false,'common_app','No Essay Required (Per Third-Party Summary; Official Page Access Blocked)',null,'c0b838d6-1e0a-470f-b90f-11df0dea68ff',null,null,null,null,null,null,null,null,null,'unconfirmed_current_year','2026-09-24','WVU 공식 admissions.wvu.edu, wvu.edu 두 도메인 모두 WebFetch에서 403으로 직접 fetch 실패(SSL/403 목록 추가 대상). 검색 요약 기준 "No essays or recommendations are required" 이나 공식 페이지 문구 직접 확인 안 됨. 다음 세션 브라우저 자동화 등으로 재확인 필요.');
